#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.creakingParticles)]
    public class CreakingParticles : EntityBehaviourDefinition
    {

        #region 公有方法
        public CreakingParticles(string nsp, string name) : base(nsp, name)
        {
        }
        #endregion

        public override void Update(Entity entity)
        {
            base.Update(entity);
            var t = 1 - (entity.Timeout - EXTRA_TIMEOUT) / (float)(entity.GetMaxTimeout() - EXTRA_TIMEOUT);
            var source = entity.GetProperty<Vector3>(PROP_SOURCE_POSITION);
            var target = entity.GetProperty<Vector3>(PROP_TARGET_POSITION);
            entity.Position = Vector3.Lerp(source, target, t);
        }
        public static readonly VanillaEntityPropertyMeta<Vector3> PROP_SOURCE_POSITION = new VanillaEntityPropertyMeta<Vector3>("source_position");
        public static readonly VanillaEntityPropertyMeta<Vector3> PROP_TARGET_POSITION = new VanillaEntityPropertyMeta<Vector3>("target_position");
        public const int EXTRA_TIMEOUT = 15;
    }
}